    pax = 0
    for age in ages:
        if age >= 16:
            pax += a
        elif age >= 5:
            pax += half_up(Fraction(a, 2))
    mins = depart[0] * 60 + depart[1]
    if 600 <= mins < 900:
        pax = half_up(Fraction(pax * 85, 100))
    total = pax + veh(dm)
    while total % 5:
        total += 1
    return total


